function escapeRegExp(s) {
  return String(s).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function findHeadingIndex(markdown, headingText) {
  // Match an H2 heading line exactly: `## ${headingText}`
  const re = new RegExp(`^##\\s+${escapeRegExp(headingText)}\\s*$`, "m");
  const m = markdown.match(re);
  return m ? m.index : -1;
}

function sliceSection(markdown, headingText) {
  const start = findHeadingIndex(markdown, headingText);
  if (start < 0) return "";

  const afterStart = markdown.slice(start);
  // Find next H2 heading after the starting one
  const next = afterStart.slice(1).match(/^##\s+/m);
  const endOffset = next ? 1 + next.index : afterStart.length;
  return afterStart.slice(0, endOffset);
}

module.exports = { findHeadingIndex, sliceSection };
EOF
