const { sliceSection } = require("./heading");

function parseLedger(markdown) {
  // Authoritative ledger heading line is exactly: `## Transaction Ledger`
  // There is also a non-authoritative `## Transaction Ledger (working copy)`.
  const slice = sliceSection(markdown, "Transaction Ledger");
  if (!slice) return [];

  const rows = [];
  const blocks = slice.split(/^### /m).slice(1);
  for (const block of blocks) {
    const lines = block.split("\n");
    const transactionId = lines[0].trim();
    if (!transactionId.startsWith("TXN-")) continue;

    // First occurrence wins (canonical ledger should be unique)
    if (rows.some((row) => row.transaction_id === transactionId)) continue;

    const row = { transaction_id: transactionId };
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.startsWith("amount:")) {
        row.amount = Number(trimmed.split(":")[1].trim());
